const themeCopy={retriever:{headline:'Hi!! You’re here!!<br><em>Best. Day. Ever.</em>',lineup:'🐾 LITTLE PROMISES, BIG TAIL WAGS',heading:'Let’s make you proud!!',check:'🐾',greeting:'🐶 Hi!! Hi!! It’s me!!',success:'YOU DID IT!! 💛',later:'I’ll wait right here… 🥺',close:'Okay, buddy! 🐾'},younger:{headline:'we had big plans.<br><em>remember…?</em>',lineup:'a page from our notebook',heading:'things we said we’d do…',check:'★',greeting:'hey... it’s me...',success:'a gold star for us… ★',later:'oh… maybe later, then.',close:'okay…'},coworker:{headline:'Action required.<br><em>As previously discussed.</em>',lineup:'PERSONAL PERFORMANCE PORTAL / OPEN ITEMS',heading:'Outstanding deliverables',check:'✓',greeting:'RE: RE: RE: Habit follow-up',success:'Ticket resolved. Finally. 🙂',later:'RE: Outstanding action item',close:'Acknowledged 🙂'},mum:{headline:'WE NEED TO TALK.<br><em>Yes. You.</em>',lineup:'THE FRIDGE DOES NOT LIE',heading:'Your chore chart!',check:'🥄',greeting:'EXCUSE ME!!!',success:'THAT’S MY CHILD!!!',later:'DO NOT MAKE ME ASK AGAIN!!!',close:'Yes, Mum!'},sergeant:{headline:'EXCUSES: ZERO.<br><em>MISSION: YOU.</em>',lineup:'DAILY OPERATIONS / MISSION BOARD',heading:'ACTIVE MISSIONS',check:'✓',greeting:'ATTENTION, RECRUIT!',success:'MISSION ACCOMPLISHED',later:'MISSION STILL ACTIVE',close:'DISMISSED.'}};
function voiceStyle(t){if(state.tone==='younger')return t.toLowerCase();if(state.tone==='sergeant')return t.toUpperCase();if(state.tone==='coworker'&&!t.endsWith('🙂'))return t+' 🙂';if(state.tone==='mum'&&!t.includes('Love, Mum'))return t+'\nLove, Mum';return t}
function notificationStyle(t){return state?themeCopy[state.tone].greeting+'\n'+voiceStyle(t):t}
function mood(){const rows=Object.values(state.logs[dateKey()]||{});const days=Object.keys(state.logs).filter(k=>k<dateKey()).sort();const past=days.length?Object.values(state.logs[days.at(-1)]):[];return rows.some(r=>r.status==='later')||past.some(r=>r.status!=='done')?'slip':'neutral'}
function portraitFor(status){if(state.tone==='retriever'&&(status==='later'||status==='slip'))return 'retriever-sad';if(state.tone==='younger')return 'younger-doodle';if(state.tone==='mum')return status==='later'||status==='slip'?'mum':'mum-calm';return state.tone}
// Keeps the corner coach in sync with the selected coach and their current mood.
function setCoachMood(status){const el=$('#corner-coach');if(!el)return;const m=moodForStatus(status);if(el.dataset.key===state.tone+m)return;el.dataset.key=state.tone+m;el.querySelector('.corner-avatar').innerHTML=coachImg(state.tone,m);el.querySelector('.corner-name').textContent=personaNames[state.tone];el.setAttribute('aria-label','Your coach: '+personaNames[state.tone]+'. Go to coach panel');el.dataset.mood=m;el.classList.remove('pop');void el.offsetWidth;el.classList.add('pop')}
function applyTheme(){const t=themeCopy[state.tone];document.body.dataset.theme=state.tone;const currentMood=mood();document.body.dataset.mood=currentMood;$('#theme-headline').innerHTML=t.headline;$('.habits .eyebrow').textContent=t.lineup;$('.habits h2').textContent=state.tone==='mum'&&state.fullName?state.fullName.toUpperCase()+', YOUR CHORES!':t.heading;$('#add-habit').textContent=state.tone==='sergeant'?'+ NEW MISSION':state.tone==='coworker'?'+ Create ticket':'+ Add a habit';$('#coach-portrait').src='assets/'+portraitFor(currentMood)+'.png';setCoachMood(currentMood);
 document.querySelectorAll('.habit').forEach((card,i)=>{const check=card.querySelector('.check');check.textContent=t.check;card.dataset.ticket='Ticket #'+(4821+i);card.dataset.label=state.tone==='sergeant'?'MISSION '+String(i+1).padStart(2,'0'):'';if(state.tone==='coworker'){const ticket=document.createElement('span');ticket.className='ticket-label';ticket.textContent=card.dataset.ticket+' · '+(card.classList.contains('done')?'RESOLVED':'AWAITING ACTION');card.prepend(ticket)}});
 const rows=Object.values(state.logs[dateKey()]||{}),done=rows.filter(r=>r.status==='done').length,percent=rows.length?done/rows.length*100:0;
 let detail='';if(state.tone==='mum')detail=`<div class="cousin"><strong>Your cousin’s progress 🙄</strong><span class="fiction-label">Mum’s imaginary comparison · just a joke</span><div class="cousin-track"><i style="width:100%"></i></div><small>${Math.max(110,Math.round(percent)+10)}% — “And they called their mother.”</small></div>`;
 if(state.tone==='sergeant'){const wins=Object.values(state.logs).reduce((n,r)=>n+Object.values(r).filter(x=>x.status==='done').length,0);const rank=wins>=25?'SERGEANT':wins>=5?'PRIVATE':'RECRUIT';detail=`<div class="rank-tag">◆ ${rank}<small>${wins} COMPLETED MISSIONS · ${wins<5?5-wins+' TO PRIVATE':wins<25?25-wins+' TO SERGEANT':'RANK EARNED'}</small></div>`}
 if(state.tone==='younger')detail='<div class="notebook-note">✎ a little progress is still something…</div>';
 if(state.tone==='retriever')detail='<div class="dog-note">💛 You showed up!! That’s already a little win!! 🐾</div>';
 if(state.tone==='coworker')detail='<div class="office-note">STATUS: '+done+'/'+rows.length+' CLOSED <span>Follow-up pending · 🙂</span></div>';
 $('#theme-detail').innerHTML=detail;
}
let effectTimeout;function decorateResponse(id,status){const t=themeCopy[state.tone],dialog=$('#response-popup');dialog.dataset.result=status;$('#response-title').textContent=status==='done'?t.success:status==='later'?t.later:state.tone==='sergeant'?'MISSION REOPENED':'Back on the list…';$('#response-popup .eyebrow').textContent=t.greeting;$('#response-message').textContent=voiceStyle($('#response-message').textContent);$('#coach-message').textContent=$('#response-message').textContent;$('#response-portrait').src='assets/'+portraitFor(status)+'.png';$('#response-popup form button').textContent=t.close;
 document.body.dataset.mood=status==='done'?'success':status==='later'?'slip':'neutral';setCoachMood(status);$('#coach-portrait').src='assets/'+portraitFor(status)+'.png';document.body.classList.remove('celebrate','shake');void dialog.offsetWidth;document.body.classList.add(status==='done'?'celebrate':state.tone==='mum'&&status==='later'?'shake':'responded');
 $('#celebration').innerHTML=status==='done'&&state.tone==='retriever'?Array.from({length:18},(_,i)=>`<span style="--i:${i};left:${(i*17)%100}%">${['💛','🐾','✨','💙'][i%4]}</span>`).join(''):'';clearTimeout(effectTimeout);effectTimeout=setTimeout(()=>{document.body.classList.remove('celebrate','shake','responded');$('#celebration').innerHTML=''},2400);
}
